import json, tomllib; from familiar.cli import main

def test_feedback_intake_journey(family):
    inbox = family.root / 'family/feedback/inbox'; inbox.mkdir(parents=True); ids = ['11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222']
    for identity, relation in zip(ids, ['father', 'sibling']):
        (inbox / (identity + '.json')).write_text(json.dumps({'id': identity, 'kind': 'add_person', 'anchor': 'p-amaro', 'relation': relation, 'received_at': '2026-01-01T12:00:00Z', 'text': 'Literal &amp; words ' + relation, 'new_person': {'given': relation, 'birth': 'circa 1900', 'birth_place': 'Here', 'living': 'dead', 'known_from': 'memory'}}), encoding='utf-8')
    mark = family.root / 'family/feedback/read' / (ids[0] + '.json'); mark.parent.mkdir(parents=True); mark.write_text('{"by":"earlier"}', encoding='utf-8'); args = ['--root', str(family.root), 'intake']; path = family.root / 'inputs/draft.toml'
    assert main(args + ['feedback-draft', *ids, '--output', 'inputs/draft.toml', '--id', 'example', '--told-by', 'Narrator']) == 0; draft = tomllib.loads(path.read_text(encoding='utf-8')); assert draft['items'][0]['text'] == 'Literal &amp; words father'
    people_path = family.root / 'tree/snapshot/people.json'; snap = json.loads(people_path.read_text(encoding='utf-8')); next(x for x in snap['people'] if x['id'] == 'p-amaro')['placeholder'] = 'Bridge label'; people_path.write_text(json.dumps(snap), encoding='utf-8')
    path.write_text(path.read_text(encoding='utf-8') + '\n[[people]]\nid = "amaro"\nexisting = "p-amaro"\nnames = [{given = "Told", type = "reported", provenance = ["%s"]}]\n' % draft['items'][0]['id'], encoding='utf-8'); assert main(args + ['memory', str(path), '--by', 'Researcher']) == 0
    persons = json.loads((family.root / 'tree/snapshot/people.json').read_text(encoding='utf-8'))['people']; families = json.loads((family.root / 'tree/snapshot/families.json').read_text(encoding='utf-8'))['families']; assert {'example-person1', 'example-person2'} <= {p['id'] for p in persons}; assert 'placeholder' not in next(p for p in persons if p['id'] == 'p-amaro'); assert any(f.get('status') == 'hypothesis' and 'example-person2' in f['children'] and f['wife'] == 'p-joaquina' for f in families); assert json.loads(mark.read_text(encoding='utf-8')) == {'by': 'earlier'}
    receipt = json.loads((mark.parent / (ids[1] + '.json')).read_text(encoding='utf-8')); assert receipt['intake'] == 'example' and receipt['by'] == 'Researcher'; memory = json.loads((family.path('memory') / 'example.json').read_text(encoding='utf-8')); assert memory['items'][0]['text'] == draft['items'][0]['text']
